transforms.code:

security = value['security']
canCreate = False
canEdit = False
if security['userCRUD'] is not None and security['userId'] is not None:
	if security['userCRUD']['isGatewayAdmin'] or security['userCRUD']['configureLots']['enabled']: 
		canCreate = True
		canEdit = True if len(list(value['routeSteps'])) > 0 else False

return {"canCreate": canCreate, "canDelete": canEdit, "canRead": True, "canUpdate": canEdit}


routeStepEvents = system.kanoa.utilities.convertDatasetToJSON(system.kanoa.lot.getRouteStepEvents({'routeEventId': value['routeEventId'] or -1}))
lotEvents = system.kanoa.utilities.convertDatasetToJSON(system.kanoa.lot.getLotEvents({'lotId': value['lotId'] or -1, 'itemSourceName': 'output'}))

routeOperations = {}
for row in routeStepEvents:
	routeOperations[row['lotOperationName']] = 0

for routeStepEvent in routeStepEvents:
	routeStepEvent['lotEventId'] = None
	routeStepEvent['lotStateName'] = None
	routeStepEvent['lotStateReasonName'] = None
	routeStepEvent['status'] = None

for routeStepEvent in routeStepEvents:
	for i, lotEvent in enumerate(lotEvents):
		if lotEvent['lotOperationName'] == routeStepEvent['lotOperationName']:
			if i >= routeOperations[routeStepEvent['lotOperationName']]:
				routeStepEvent['lotEventId'] = lotEvent['lotEventId']
				routeStepEvent['lotStateName'] = lotEvent['lotStateName']
				routeStepEvent['lotStateReasonName'] = lotEvent['lotStateReasonName']
				routeStepEvent['status'] = "%s %s"%(lotEvent['lotStateName'], lotEvent['lotStateReasonName'] or '')
				routeOperations[routeStepEvent['lotOperationName']] += 1
				break

return routeStepEvents
